// ✅ Dynamic tasks per day
const TASKS_PER_DAY = parseInt(localStorage.getItem("tasksPerDay")) || 3;

const completedDays = JSON.parse(localStorage.getItem("completedDays") || "[]");

// ✅ Correct total tasks calculation
const totalTasks = Array.isArray(roadmapPlan)
  ? roadmapPlan.reduce((sum, phase) => sum + phase.length, 0)
  : 0;

// ✅ Correct total days
const totalDays = Math.ceil(totalTasks / TASKS_PER_DAY);

const completedCount = completedDays.length;
const remainingDays = Math.max(totalDays - completedCount, 0);

const completionPercentage =
  totalDays > 0
    ? Math.min(100, Math.round((completedCount / totalDays) * 100))
    : 0;
